from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/gold-standard-2026'
D=json.loads((OUT/'Consolidated_Course_Data.json').read_text())
style=(OUT/'Teacher_Guide.html').read_text().split('<style>')[1].split('</style>')[0]
html=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>My skill passport</title><style>STYLE_PLACEHOLDER</style></head><body><header><div class="tag">My learning · My evidence · My next step</div><h1>My skill passport</h1><p>Keep a short record when you use a skill. Show what you did, point to the evidence, and choose one next action.</p></header><main><div class="note">This file stores entries only in this browser. Keep an exported copy. Your self-rating is for reflection; your teacher makes a separate judgment from the evidence. Use your school’s normal private submission channel. Do not paste passwords or personal histories.</div><form class="card" id="claimForm"><h2>Record one meaningful use</h2><div class="grid"><div><label for="course">Course</label><select id="course"><option value="MM12">Multimedia 12</option><option value="COM11">Communications Technology 11</option><option value="IBDS">IB Digital Society</option></select></div><div><label for="student">My student ID</label><input id="student" required maxlength="150" autocomplete="off"><p class="small">Use the ID your teacher provides so your evidence reaches your own profile.</p></div><div><label for="date">Date I used the skill</label><input id="date" type="date" required></div><div><label for="attempt">Task or project</label><input id="attempt" required maxlength="500"></div></div><label for="skill">Skill I used</label><select id="skill"></select><p id="skillEvidence"></p><details><summary>What the four reflection levels mean for this skill</summary><ol id="anchors"></ol></details><label for="note">What I actually did</label><textarea id="note" required maxlength="5000" placeholder="Name the decision, action or repair. Point to the part of the work that demonstrates it."></textarea><label for="learned">What I learned or understand better</label><textarea id="learned" maxlength="5000" placeholder="Explain what changed in your understanding; name one cause and effect."></textarea><div class="grid"><div><label for="artifact">Evidence link or filename and location</label><input id="artifact" required maxlength="2000" placeholder="A school-approved link, or a file and the relevant layer / timecode / paragraph"></div><div><label for="selfRating">My self-rating for this attempt</label><select id="selfRating"><option value="">Unsure</option><option value="1">1 · Beginning</option><option value="2">2 · Developing</option><option value="3">3 · Independent</option><option value="4">4 · Transfer</option></select></div><div><label for="support">Help used during this attempt</label><select id="support"><option>None</option><option>Access supports only</option><option>Instructional hints</option><option>Modelled together</option></select></div><div><label for="next">My next action</label><input id="next" required maxlength="1000" placeholder="One thing I will practise or check"></div></div><p class="small">Access supports help you take part, such as extra time or an assistive input device. Instructional hints help solve this particular task. Record honestly; the purpose is choosing helpful practice.</p><div class="buttons"><button>Save this skill use</button></div><p id="status" role="status" aria-live="polite"></p></form><div class="card"><h2>My evidence history</h2><p>Showing the selected course and student ID. Submit this course’s JSON to your teacher. Keep the full backup for yourself.</p><div class="buttons"><button id="export">Export this course for teacher</button><button id="backup">Download full private backup</button><button id="print">Print my log</button></div><label for="restore">Restore my private backup</label><input id="restore" type="file" accept=".json"><div id="restoreReview"></div><h2>My progress dashboard</h2><p class="small">Practice counts and recency describe opportunities. Self-ratings are reflections, not teacher grades.</p><div id="dashboard"></div><div id="history"></div></div></main><script>
const SKILLS=DATA_PLACEHOLDER;
const KEY='em_student_passport_v1';const $=id=>document.getElementById(id);const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>{const d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');};
const uid=()=>crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2);
let claims=[],loadError='';
function valid(c){return c&&typeof c==='object'&&(c.learned===undefined||typeof c.learned==='string'&&c.learned.length<=5000)&&['id','course','student','skill','date','note','attempt','artifact','next','support'].every(k=>typeof c[k]==='string'&&c[k].length<50001)&&['MM12','COM11','IBDS'].includes(c.course)&&SKILLS.some(s=>s.id===c.skill&&(s.course===c.course||s.course==='ALL'))&&/^\d{4}-\d{2}-\d{2}$/.test(c.date)&&!isNaN(Date.parse(c.date))&&new Date(c.date+'T12:00:00Z').toISOString().slice(0,10)===c.date&&c.date<=today()&&[c.id,c.student,c.note,c.attempt,c.artifact].every(s=>s.trim())&&(c.selfRating===null||[1,2,3,4].includes(c.selfRating))&&['None','Access supports only','Instructional hints','Modelled together'].includes(c.support);}
try{const raw=localStorage.getItem(KEY);if(raw){const data=JSON.parse(raw);if(!Array.isArray(data)||!data.every(valid)||new Set(data.map(c=>c.id)).size!==data.length)throw Error('Saved entries need recovery.');claims=data;}}catch(e){loadError=e.message;$('status').textContent='Saved data could not be read. Download the full backup before restoring a known good copy. '+e.message;}
function save(next,recover=false){if(loadError&&!recover){$('status').textContent='Saved data needs recovery first.';return false;}try{localStorage.setItem(KEY,JSON.stringify(next));claims=next;loadError='';return true;}catch(e){$('status').textContent='Not saved. Browser storage is unavailable or full. Export a backup.';return false;}}
function download(data,name){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type:'application/json'}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),3000);}
function selected(){return claims.filter(c=>c.course===$('course').value&&c.student===$('student').value.trim());}
function render(){const rows=selected().slice().sort((a,b)=>b.date.localeCompare(a.date));$('dashboard').innerHTML='<div class="table-wrap"><table><thead><tr><th>Skill</th><th>Meaningful uses</th><th>Last practised</th><th>Latest self-rating</th></tr></thead><tbody>'+SKILLS.filter(s=>s.course===$('course').value||s.course==='ALL').map(s=>{const uses=rows.filter(c=>c.skill===s.id);return '<tr><td>'+esc(s.name)+'</td><td>'+uses.length+'</td><td>'+esc(uses[0]?.date||'Not yet logged')+'</td><td>'+(uses[0]?.selfRating??'—')+'</td></tr>';}).join('')+'</tbody></table></div>';$('history').innerHTML=rows.length?rows.map(c=>`<div class="card"><h3>${esc(SKILLS.find(s=>s.id===c.skill).name)}</h3><p class="small">${esc(c.date)} · ${esc(c.attempt)} · Self-rating ${c.selfRating??'unsure'}</p><p>${esc(c.note)}</p>${c.learned?`<p><b>Learning:</b> ${esc(c.learned)}</p>`:''}<p class="small">Evidence: ${esc(c.artifact)}<br>Help: ${esc(c.support)}</p><p>Next: ${esc(c.next)}</p></div>`).join(''):'<p>No saved claims for this course and student ID yet.</p>';}
function anchors(){const s=SKILLS.find(s=>s.id===$('skill').value);$('skillEvidence').textContent=s.evidence;$('anchors').innerHTML=s.descriptors.map(v=>'<li>'+esc(v)+'</li>').join('');}
function course(){const rows=SKILLS.filter(s=>s.course===$('course').value||s.course==='ALL');$('skill').innerHTML=rows.map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');anchors();render();}
$('course').onchange=course;$('student').onchange=render;$('skill').onchange=anchors;$('date').value=today();$('date').max=today();
if(claims.length){$('course').value=claims.at(-1).course;$('student').value=claims.at(-1).student;}course();
$('claimForm').onsubmit=e=>{e.preventDefault();const c={id:uid(),course:$('course').value,student:$('student').value.trim(),date:$('date').value,attempt:$('attempt').value.trim(),skill:$('skill').value,note:$('note').value.trim(),learned:$('learned').value.trim(),artifact:$('artifact').value.trim(),selfRating:$('selfRating').value?Number($('selfRating').value):null,support:$('support').value,next:$('next').value.trim()};if(!valid(c)){$('status').textContent='Check the date, student ID and evidence fields.';return;}if(save([...claims,c])){$('status').textContent='Skill use saved. Export this course when you are ready to submit.';$('note').value='';$('learned').value='';$('selfRating').value='';render();}};
$('export').onclick=()=>{const rows=selected();if(!rows.length){$('status').textContent='Save a skill use for this course and student ID first.';return;}download(JSON.stringify({app:'evidence-map-student-passport',schema:1,exportedAt:new Date().toISOString(),claims:rows},null,2),'My_'+$('course').value+'_Skill_Passport.json');};
$('backup').onclick=()=>download(loadError?(localStorage.getItem(KEY)||''):JSON.stringify({app:'evidence-map-student-passport',schema:1,claims},null,2),'My_Skill_Passport_Backup.json');
$('print').onclick=()=>window.print();
$('restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error('File exceeds 2 MB.');const p=JSON.parse(await f.text());if(p.app!=='evidence-map-student-passport'||p.schema!==1||!Array.isArray(p.claims)||p.claims.length>2000||!p.claims.every(valid)||new Set(p.claims.map(c=>c.id)).size!==p.claims.length)throw Error('Invalid passport backup.');$('restoreReview').innerHTML=`<p>Replace this browser’s log with ${p.claims.length} claims? Download your current backup first.</p><button id="confirmRestore">Replace my log with this backup</button><button id="cancelRestore">Cancel</button>`;$('confirmRestore').onclick=()=>{if(save(p.claims,true)){if(claims.length){$('course').value=claims.at(-1).course;$('student').value=claims.at(-1).student;}course();$('restoreReview').replaceChildren();$('status').textContent='Private backup restored.';}};$('cancelRestore').onclick=()=>$('restoreReview').replaceChildren();}catch(e){$('restoreReview').textContent='Restore blocked: '+e.message;}};
</script></body></html>'''
html=html.replace('STYLE_PLACEHOLDER',style+'.table-wrap{max-width:100%;overflow-x:auto}#dashboard table{min-width:640px}@media print{#claimForm,.note,#restore,#restoreReview,label[for=restore]{display:none}}').replace('DATA_PLACEHOLDER',json.dumps(D['skills'],ensure_ascii=False).replace('</','<\\/'))
(OUT/'Student_Skill_Passport.html').write_text(html)
print('Built standalone student passport')
